('da474a84-6d4b-5f9a-9dd1-e41243c2017d'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Convene regular CDRRMC meeting',null,'a37bb249-1b6f-585a-8b12-bc80b742cc63'::uuid,null,1),('e6d57c5d-f148-58e5-82fe-75e25c28c98a'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Prepare agenda and technical briefs',null,null,null,2),('66ca7c07-51eb-591e-8ecc-8e70478d7bcf'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Review Local DRRM Plan',null,null,null,3),('4de11426-fd91-56b1-aef2-c481d5055a8a'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Integrate DRRM into local plans and investment programming','Each office remains accountable for its own statutory planning and technical functions. CPDO retains its role in local development and land use planning; CDRRMO provides DRRM risk information and technical integration support.',null,null,4),('d637e427-807a-56e0-be77-7e0d1b2cadca'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Adopt CDRRMC resolutions',null,null,null,5),('72206f5e-6abe-5688-ac70-1cab11776e0e'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Monitor Council decisions',null,null,null,6),('2d928efc-fb06-597b-94f6-67c26afe81ad'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Update membership and focal persons',null,null,null,7),('f251347e-f0b0-5282-9256-701d87ff4b9f'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Conduct annual governance review',null,null,null,8),('9c95f157-d1c3-5ecd-b336-00b4a41d4a94'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Recommend State of Calamity',null,'f99e18a5-6514-56f9-8bf6-dc31df80cd6f'::uuid,null,9),('bc1d7a76-d644-5f2c-941c-fd7d0688e7eb'::uuid,'b6153aa9-7ec3-576d-88bb-b3623c1a504c'::uuid,'Recommend State of Imminent Disaster through the legally required channel','The exact SID recommendation route must be aligned with Republic Act No. 12287 and its IRR. The matrix must be revised if the certified legal text assigns the recommendation to a regional or other competent authority. The City Mayor